const analyzerLauncher = resolve(packageDirectory, "bin/solid-migration-assistant.mjs");
const SUMMARY_PREFIX = "[solid-migration-assistant] Summary: ";

/** Headlines of the launcher-side findings, which Codemod does not indent. */
function launcherFindings(stdout) {
  return stripAnsi(stdout)
    .split("\n")
    .filter((line) => /^(?:package|tsconfig)\.json:\d+:\d+ /.test(line));
}

/**
 * Exercises the read-only analyze workflow end to end through the published
 * launcher: exact, deterministic guidance for the checked-in fixture (which
 * includes a cross-file reference that only workspace-semantic analysis can
 * resolve), byte-identical output across two runs, a clean run on a project
 * with no supported sites, a relative --target, and proof that no run writes
 * into the target or leaves analyzer artifacts there.
 */
const temporaryRoot = mkdtempSync(
  join(tmpdir(), "solid-migration-assistant-workflow-"),
);
try {
  assert.deepEqual(
    [...expectedGuidance].sort(),
    expectedGuidance,
    "expectedGuidance must be listed in the analyzer's whole-string sort order",
  );
  assert.equal(new Set(expectedGuidance).size, expectedGuidance.length);

  const target = join(temporaryRoot, "fixture");
  cpSync(fixtureDirectory, target, { recursive: true });
  const before = treeSnapshot(target);

  const first = runAnalyzer(["--target", target]);
  assert.equal(first.status, 0, output(first));
  assert.deepEqual(guidanceBlocks(first.stdout), expectedGuidance);
  // The launcher's own read-only findings for the manifest and tsconfig print
  // first, unindented, before the Codemod-run guidance block.
  assert.deepEqual(launcherFindings(first.stdout), [
    "package.json:1:1 Manual review required: move this project's Solid dependencies to solid-js@2.0.0-rc.21.",
    "tsconfig.json:1:1 Manual review required: point jsxImportSource at the Solid 2 renderer package.",
  ]);
  assertSummary(first.stdout, expectedGuidance);
  assertFinalDisclosure(first.stderr);
  assertDetectionOnlyTerminalOutput(first.stdout + first.stderr);
  assert.deepEqual(treeSnapshot(target), before, "the first run changed the target");
  assertNoPersistentArtifacts(target);

  const second = runAnalyzer(["--target", target]);
  assert.equal(second.status, 0, output(second));
  assert.equal(
    stripAnsi(second.stdout),
    stripAnsi(first.stdout),
    "guidance changed between two runs on the same target",
  );
  assert.deepEqual(treeSnapshot(target), before, "the second run changed the target");
  assertNoPersistentArtifacts(target);

  // --format json carries the same findings, plus the launcher's two
  // project-file findings, as one parseable document, and is just as
  // read-only.
  const json = runAnalyzer(["--target", target, "--format", "json"]);
  assert.equal(json.status, 0, output(json));
  const report = JSON.parse(json.stdout);
  assert.equal(report.status, 0);
  assert.equal(report.summary.findings, expectedGuidance.length + 2);
  assert.deepEqual(
    report.findings.filter((finding) => finding.file.startsWith("src/")).map((finding) => finding.text).sort(),
    [...expectedGuidance],
  );
  for (const finding of report.findings) {
    assert.equal(finding.severity, severityOf(finding.headline));
  }
  assert.deepEqual(treeSnapshot(target), before, "the JSON run changed the target");

  // A relative --target resolves against the invocation directory.
  const relative = runAnalyzer(["--target", "fixture"], temporaryRoot);
  assert.equal(relative.status, 0, output(relative));
  assert.deepEqual(guidanceBlocks(relative.stdout), expectedGuidance);
  assert.deepEqual(treeSnapshot(target), before, "the relative run changed the target");

  // A project with no supported migration sites prints no guidance at all.
  const empty = join(temporaryRoot, "empty");
  cpSync(emptyDirectory, empty, { recursive: true });
  const emptyBefore = treeSnapshot(empty);
  const emptyRun = runAnalyzer(["--target", empty]);
  assert.equal(emptyRun.status, 0, output(emptyRun));
  assert.deepEqual(guidanceBlocks(emptyRun.stdout), []);
  assert.deepEqual(summaryLines(emptyRun.stdout), []);
  assert.deepEqual(launcherFindings(emptyRun.stdout), []);
  assertFinalDisclosure(emptyRun.stderr);
  assert.deepEqual(treeSnapshot(empty), emptyBefore, "the empty run changed the target");
  assertNoPersistentArtifacts(empty);

  console.log(
    `Workflow guidance passed: ${expectedGuidance.length} exact findings, 2 targets unchanged.`,
  );
} finally {
  rmSync(temporaryRoot, { recursive: true, force: true });
}

/**
 * The summary must be derivable from the findings themselves: one header with
 * the total and file count, then for each distinct headline (sorted) a count
 * line and the sorted site list.
 */
function assertSummary(stdout, findings) {
  const byHeadline = new Map();
  const files = new Set();
  for (const finding of findings) {
    const match = /^(\S+:\d+:\d+) (.*)$/.exec(finding.split("\n")[0]);
    files.add(match[1].slice(0, match[1].indexOf(":")));
    byHeadline.set(match[2], [...(byHeadline.get(match[2]) ?? []), match[1]]);
  }
  const expected = [
    `${SUMMARY_PREFIX}${findings.length} findings in ${files.size} file(s)`,
  ];
  // Grouped by severity tier in fix order; headlines sorted within a tier.
  for (const tier of SEVERITY_TIERS) {
    const headlines = [...byHeadline.keys()].filter((headline) => severityOf(headline) === tier.id).sort();
    if (headlines.length === 0) continue;
    const count = headlines.reduce((sum, headline) => sum + byHeadline.get(headline).length, 0);
    expected.push(`${tier.label}: ${count} findings`);
    for (const headline of headlines) {
      const sites = byHeadline.get(headline);
      expected.push(`${String(sites.length).padStart(4)}  ${headline}`);
      expected.push(`      sites: ${[...sites].sort().join(", ")}`);
    }
  }
  assert.deepEqual(summaryLines(stdout), expected);
}

function runAnalyzer(argumentsList, cwd = packageDirectory) {
  return spawnSync(process.execPath, [analyzerLauncher, ...argumentsList], {
    cwd,
    encoding: "utf8",
    env: { ...process.env, CI: "true", NO_COLOR: "1", FORCE_COLOR: undefined },
    maxBuffer: 10 * 1024 * 1024,
  });
}

/**
 * The launcher prints the analyzer's guidance to stdout through the Codemod
 * runtime, which indents every console line by two spaces and may add bare
 * progress lines of its own; the guidance block is the indented text, with
 * one blank line between findings.
 */
function guidanceBlocks(stdout) {
  const lines = stripAnsi(stdout)
    .split("\n")
    .filter((line) => line.startsWith("  "))
    .map((line) => line.slice(2));
  const summary = lines.findIndex((line) => line.startsWith(SUMMARY_PREFIX));
  const text = (summary === -1 ? lines : lines.slice(0, summary)).join("\n").trim();
  return text === "" ? [] : text.split("\n\n");
}


/**
 * The summary tail printed after the guidance: its header plus one count line
 * and one `sites:` line per distinct headline.
 */
function summaryLines(stdout) {
  const lines = stripAnsi(stdout)
    .split("\n")
    .filter((line) => line.startsWith("  "))
    .map((line) => line.slice(2));
  const summary = lines.findIndex((line) => line.startsWith(SUMMARY_PREFIX));
  return summary === -1 ? [] : lines.slice(summary).filter((line) => line.trim() !== "");
}

function assertFinalDisclosure(value) {
  const stripped = stripAnsi(value).trimEnd();
  assert.ok(stripped.endsWith(DISCLOSURE));
  assert.equal(
    stripped.split("[solid-migration-assistant] Final disclosure").length - 1,
    1,
  );
}

function stripAnsi(value) {
  return value.replace(/\u001b\[[0-?]*[ -/]*[@-~]/g, "");
}

function assertDetectionOnlyTerminalOutput(value) {
  assert.doesNotMatch(
    stripAnsi(value),
    /codemod-reports|migration report|safe-transform|agent-guided|confidence/i,
  );
}

function assertNoPersistentArtifacts(target) {
  for (const path of [
    ".codemod",
    ".codemod-reports",
    "build",
    "coverage",
    "dist",
  ]) {
    assert.equal(existsSync(join(target, path)), false, path);
  }
}
